<script setup lang="ts">
import { Head } from '@inertiajs/vue3';
import { onMounted, ref } from 'vue';
import AppShell from '../components/AppShell.vue';
import { api, type DashboardData, type CurrentUser } from '../lib/api';
const data = ref<DashboardData | null>(null); const user = ref<CurrentUser | null>(null); const error = ref('');
const money = (value: number | undefined) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value ?? 0);
onMounted(async () => { try { user.value = (await api.me()).data; data.value = (await api.dashboard()).data; } catch (e) { error.value = e instanceof Error ? e.message : 'Unable to load dashboard.'; } });
</script>
<template>
    <Head title="Dashboard" /><AppShell title="Overview" :user="user"><section class="mx-auto max-w-7xl space-y-6 p-5 sm:p-8"><div><p class="text-xs font-bold uppercase tracking-widest text-teal-700">RENTAL OPERATIONS</p><h1 class="mt-2 text-3xl font-bold tracking-tight text-slate-800">Good morning, {{ user?.name.split(' ')[0] }}</h1><p class="mt-1 text-sm text-slate-500">Here is what is happening across your properties today.</p></div><p v-if="error" class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{ error }}</p><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div v-for="card in [{ label: 'Total rooms', value: data?.rooms.total, note: `${data?.rooms.available ?? 0} available` }, { label: 'Occupancy rate', value: `${data?.rooms.occupancy_rate ?? 0}%`, note: `${data?.rooms.occupied ?? 0} occupied` }, { label: 'Collected this month', value: money(data?.finance.collected_total), note: 'Collected revenue' }, { label: 'Outstanding balance', value: money(data?.finance.outstanding_total), note: `${data?.finance.overdue_invoice_count ?? 0} overdue invoices` }]" :key="card.label" class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><p class="text-sm text-slate-500">{{ card.label }}</p><strong class="mt-3 block text-2xl text-slate-800">{{ card.value ?? '—' }}</strong><small class="mt-2 block text-slate-400">{{ card.note }}</small></div></div><div class="grid gap-6 lg:grid-cols-2"><article class="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><h2 class="font-semibold text-slate-800">Portfolio occupancy</h2><p class="mt-1 text-sm text-slate-500">Current room availability</p><div class="mt-8 flex items-center justify-center gap-10"><div class="grid size-40 place-items-center rounded-full" :style="{ background: `conic-gradient(#0f766e ${data?.rooms.occupancy_rate ?? 0}%, #e2e8f0 0)` }"><div class="grid size-28 place-items-center rounded-full bg-white"><strong class="text-2xl text-slate-800">{{ data?.rooms.occupancy_rate ?? 0 }}%</strong></div></div><div class="space-y-3 text-sm text-slate-500"><p>Occupied <b class="ml-5 text-slate-800">{{ data?.rooms.occupied ?? 0 }}</b></p><p>Available <b class="ml-5 text-slate-800">{{ data?.rooms.available ?? 0 }}</b></p><p>Reserved <b class="ml-5 text-slate-800">{{ data?.rooms.reserved ?? 0 }}</b></p><p>Maintenance <b class="ml-5 text-slate-800">{{ data?.rooms.maintenance ?? 0 }}</b></p></div></div></article><article class="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><h2 class="font-semibold text-slate-800">Financial performance</h2><p class="mt-1 text-sm text-slate-500">Current period summary</p><div class="mt-6 space-y-4 text-sm"><p class="flex justify-between border-b pb-3 text-slate-500">Invoices issued <b class="text-slate-800">{{ money(data?.finance.invoices_total) }}</b></p><p class="flex justify-between border-b pb-3 text-slate-500">Collected revenue <b class="text-emerald-700">{{ money(data?.finance.collected_total) }}</b></p><p class="flex justify-between border-b pb-3 text-slate-500">Operating expenses <b class="text-slate-800">{{ money(data?.finance.expenses_total) }}</b></p><p class="flex justify-between text-slate-500">Net operating result <b class="text-teal-700">{{ money(data?.finance.net_operating_result) }}</b></p></div></article></div></section></AppShell>
</template>
